#pragma once
#include "voice_worker_fixture.hpp"
#include <companion/muse_voice_admission.hpp>
using namespace companion::muse;
struct Harness {int loads=0,finds=0,connects=0,sends=0,reads=0,lookup_closes=0,socket_closes=0,socket_destroyed=0;bool credential=true,network=true,voice=true,lookup_join=true,socket_join=true,wrong_node=false,wrong_vm=false;int fail_send=0;std::function<void()> load_hook,find_hook,connect_hook,send_hook;const char* access=nullptr;const char* bearer=nullptr;};
struct Reader:DeviceCredentialReader {Harness& h;explicit Reader(Harness& v):h(v){}bool Current()const{return h.credential;}bool LoadAccess(const std::string&,std::function<bool()> current,DeviceRecord& out)override{++h.loads;if(!current())return false;out.node=h.wrong_node?"other-device":"synthetic-device";assert(out.access.Set("synthetic-access"));assert(out.refresh.Set("synthetic-refresh"));h.access=out.access.Get();if(h.load_hook)h.load_hook();return true;}};
struct Lookup {Harness& h;std::function<bool()> current;Lookup(Harness& v,std::function<bool()> c):h(v),current(std::move(c)){}bool FindExactVm(const DeviceRecord& r,const std::string& vm,VmCredential& out){++h.finds;assert(vm=="synthetic-vm"&&!r.refresh.Size()&&r.access.Size());if(!current())return false;out.vm=h.wrong_vm?"other-vm":vm;assert(out.bearer.Set("synthetic-bearer"));h.bearer=out.bearer.Get();if(h.find_hook)h.find_hook();return true;}bool CloseAndJoin(unsigned timeout){assert(timeout<=20);++h.lookup_closes;return h.lookup_join;}};
struct NativeSocket:Socket {Harness& h;bool msg2=false,established=false;std::function<bool()> current;NativeSocket(Harness& v,std::function<bool()> c):h(v),current(std::move(c)){}~NativeSocket(){++h.socket_destroyed;}bool ConnectMeta(const std::string& vm,const char* bearer,unsigned timeout){++h.connects;assert(vm=="synthetic-vm"&&timeout&&timeout<=5000&&std::string(bearer)=="synthetic-bearer");assert(h.lookup_closes&&std::all_of(h.access,h.access+16,[](auto c){return c==0;}));if(h.connect_hook)h.connect_hook();return true;}bool Send(const uint8_t* p,size_t n,unsigned timeout){++h.sends;assert(timeout&&timeout<=1000);if(!established)assert(std::all_of(h.bearer,h.bearer+16,[](auto c){return c==0;}));if(h.send_hook)h.send_hook();if(h.fail_send==h.sends)return false;bool sent=Socket::Send(p,n,std::min(timeout,100u));if(msg2){established=true;h.bearer=nullptr;}return sent;}int Receive(uint8_t* p,size_t n,unsigned timeout){++h.reads;if(!msg2){assert(n==512&&timeout&&timeout<=2000);std::memset(p,0,tn::InitiatorHandshake::kMinMessage2Size);msg2=true;return int(tn::InitiatorHandshake::kMinMessage2Size);}return Socket::Receive(p,n,timeout);}bool CloseAndJoin(unsigned timeout){++h.socket_closes;return h.socket_join&&Socket::CloseAndJoin(timeout);}};
using Admission=VoiceAdmission<Lookup,NativeSocket>;
static_assert(sizeof(Admission)<4096,"Admission must not retain an application-sized frame buffer");
struct AdmissionOwner {Harness h;Reader reader{h};NonceTagCrypto crypto;Protocol protocol;Clock clock;Custody custody;Server server;NativeSocket* port=nullptr;std::unique_ptr<Admission> admission;
 AdmissionOwner(){admission=Admission::Create(protocol,reader,crypto,clock,custody,[this](auto c){return std::unique_ptr<Lookup>(new Lookup(h,std::move(c)));},[this](auto c){auto p=std::unique_ptr<NativeSocket>(new NativeSocket(h,std::move(c)));port=p.get();return p;});assert(admission&&!h.loads&&!h.finds&&!h.connects);}
 VoiceAdmissionScope Scope(){return {"synthetic-device","synthetic-vm",call,{7,10000000,1760000010000LL},[this]{return h.credential;},[this]{return h.network;},[this]{return h.voice;}};}
 ~AdmissionOwner(){h.lookup_join=h.socket_join=true;if(admission)assert(admission->Close());}
};
